w('src/middleware.ts', f'import {{ createServerClient }} from {dq}@supabase/ssr{dq}\nimport {{ NextResponse }} from {dq}next/server{dq}\nimport type {{ NextRequest }} from {dq}next/server{dq}\nimport createMiddleware from {dq}next-intl/middleware{dq}\nimport {{ routing }} from {dq}@/lib/i18n/routing{dq}\n\nconst handleI18n = createMiddleware(routing)\n\nexport async function middleware(request: NextRequest) {{\n  let response = NextResponse.next({{ request }})\n  const supabase = createServerClient(\n    process.env.NEXT_PUBLIC_SUPABASE_URL!,\n    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,\n    {{\n      cookies: {{\n        getAll() {{ return request.cookies.getAll() }},\n        setAll(c) {{\n          c.forEach(({{ name, value, options }}) =>\n            response.cookies.set(name, value, options))\n        }},\n      }},\n    }},\n  )\n  await supabase.auth.getUser()\n  return handleI18n(request)\n}}\n\nexport const config = {{\n  matcher: [{dq}/((?!_next|_vercel|.*\\\\..*).*){dq}],\n}}\n')
w('src/app/[locale]/layout.tsx', f'import type {{ ReactNode }} from {dq}react{dq}\nimport type {{ Locale }} from {dq}@/types{dq}\nimport {{ NextIntlClientProvider }} from {dq}next-intl{dq}\nimport {{ getMessages }} from {dq}next-intl/server{dq}\nimport {{ Inter }} from {dq}next/font/google{dq}\nimport {dq}@/styles/globals.css{dq}\n\nconst inter = Inter({{ subsets: [{dq}latin{dq}] }})\n\nexport default async function LocaleLayout({{\n  children,\n  params,\n}}: {{\n  children: ReactNode\n  params: Promise<{{ locale: Locale }}>\n}}) {{\n  const {{ locale }} = await params\n  const messages = await getMessages()\n  return (\n    <html lang={{locale}}>\n      <body className={{inter.className}}>\n        <NextIntlClientProvider messages={{messages}}>\n          {{children}}\n        </NextIntlClientProvider>\n      </body>\n    </html>\n  )\n}}\n')
